for n,x in files.items():
 b=base64.b64decode(x['base64']);assert hashlib.sha256(b).hexdigest()==x['sha256'];(source/n).write_bytes(b);(source/n).chmod(0o444)
receipt={'source_commit':'9b799ed80acaae0a099e9f84c247e9aeb38deaf8','files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in source.glob('*') if p.is_file()},'worker_saw_test_metrics_before_design':False,'coordinator_had_seen_core_test_metrics':True,'interpretation':'exploratory_followup_on_reused_holdout; not fresh confirmatory evaluation'}
